  .features-grid { grid-template-columns: 1fr; }
  .steps-grid { grid-template-columns: 1fr; }
  .stats-grid { grid-template-columns: 1fr 1fr; gap: 24px; }
  .stat-value { font-size: 36px; }

  .hero-page { padding: 110px 0 40px; }
  .hero-page .hero-title { font-size: 32px; }

  .footer-grid { grid-template-columns: 1fr; gap: 32px; }
  .footer-bottom { flex-direction: column; gap: 16px; text-align: center; }

  .team-grid { grid-template-columns: 1fr; max-width: 320px; margin: 0 auto; }

  .testimonial-card { padding: 32px 24px; }
  .testimonial-quote { font-size: 17px; }

  .cta-section { padding: 64px 0; }
  .cta-section .section-title { font-size: 28px; }

  .pricing-card { padding: 32px 24px; }
  .price-amount { font-size: 40px; }

  .btn-lg { padding: 14px 28px; font-size: 16px; }
}

@media (max-width: 480px) {
  .hero-home { padding: 110px 0 50px; }
  .hero-title { font-size: 30px !important; }
  .hero-buttons { flex-direction: column; align-items: center; }
