}
.pricing-card:hover { transform: translateY(-4px); box-shadow: 0 12px 40px rgba(0,0,0,0.08); }
.pricing-card.popular {
  border-color: var(--blue);
  box-shadow: 0 8px 32px var(--blue-glow);
}

.popular-badge {
  position: absolute;
  top: -14px;
  left: 50%;
  transform: translateX(-50%);
  background: var(--blue);
  color: var(--white);
  font-size: 13px;
  font-weight: 700;
  padding: 6px 20px;
  border-radius: 100px;
}

.pricing-tier {
  font-size: 20px;
  font-weight: 700;
  color: var(--gray-900);
  margin-bottom: 8px;
}

.pricing-price {
  display: flex;
  align-items: baseline;
  gap: 4px;
  margin-bottom: 8px;
}

.price-currency {
  font-size: 24px;
  font-weight: 700;
  color: var(--gray-400);
}

.price-amount {
  font-family: var(--font-display);
  font-size: 52px;
  font-weight: 700;
  color: var(--gray-900);
  line-height: 1;
}

.price-period {
  font-size: 15px;
  color: var(--gray-400);
}

.pricing-desc {
  font-size: 14px;
  color: var(--gray-500);
  margin-bottom: 28px;
  padding-bottom: 28px;
  border-bottom: 1px solid var(--gray-200);
}

.pricing-features {
  display: flex;
  flex-direction: column;
  gap: 14px;
  margin-bottom: 32px;
}

.pricing-feature {
  display: flex;
  align-items: flex-start;
  gap: 10px;
  font-size: 14px;
  color: var(--gray-600);
}

.pricing-feature .check {
  flex-shrink: 0;
  width: 20px;
  height: 20px;
  border-radius: 50%;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 12px;
  margin-top: 1px;
}

.check-blue { background: rgba(0,81,195,0.1); color: var(--blue); }
.check-gray { background: var(--gray-100); color: var(--gray-400); }

.pricing-card .btn { width: 100%; }

/* ---- FAQ ---- */
.faq-list {
  max-width: 720px;
  margin: 0 auto;
}

.faq-item {
  border-bottom: 1px solid var(--gray-200);
}

.faq-question {
  width: 100%;
  padding: 24px 0;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 16px;
  background: none;
  border: none;
  cursor: pointer;
  font-family: var(--font-body);
  font-size: 17px;
  font-weight: 600;
  color: var(--gray-800);
  text-align: left;
}

.faq-question:hover { color: var(--blue); }

.faq-icon {
  flex-shrink: 0;
  width: 28px;
  height: 28px;
  border-radius: 8px;
  background: var(--gray-100);
  display: flex;
