  border: 1px solid var(--gray-200);
  border-radius: 16px;
  padding: 28px;
  margin-bottom: 20px;
}

.office-card h3 {
  font-size: 18px;
  font-weight: 700;
  margin-bottom: 12px;
}

.office-info {
