.office-info span {
  display: flex;
  align-items: center;
  gap: 8px;
}

/* ---- ABOUT ---- */
.team-grid {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 32px;
}

.team-card {
  text-align: center;
  background: var(--white);
  border: 1px solid var(--gray-200);
  border-radius: 16px;
  padding: 36px 24px;
